import React, { useState } from 'react';
import { FaUser, FaLock, FaEnvelope, FaArrowRight, FaSpinner } from 'react-icons/fa';
import { motion } from 'framer-motion';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

const AuthPages = () => {
    const [isLogin, setIsLogin] = useState(true);
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    // Form State
    const [formData, setFormData] = useState({
        fullName: '',
        username: '',
        email: '',
        password: ''
    });

    // Handle Input Changes
    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    // Handle Form Submit (Backend Connection)
    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        // Basic validation
        if (!formData.username || !formData.password || (!isLogin && (!formData.fullName || !formData.email))) {
            toast.error('Please fill in all fields.');
            setLoading(false);
            return;
        }

        const endpoint = isLogin ? '/api/auth/login' : '/api/auth/register';

        try {
            const response = await axios.post(
                `http://localhost:8081${endpoint}`,
                isLogin 
                    ? { username: formData.username, password: formData.password }
                    : { 
                        fullName: formData.fullName, 
                        username: formData.username, 
                        email: formData.email, 
                        password: formData.password 
                    }
            );

            // Assuming your backend returns a JWT token and user data
            if (response.data) {
                // Save token to localStorage or your Context
                localStorage.setItem('token', response.data.token); 
                localStorage.setItem('user', JSON.stringify(response.data.user || response.data));

                toast.success(isLogin ? 'Welcome back!' : 'Account created successfully! 🎉');
                
                // Redirect to the Tracker page
                navigate('/tracker');
            }
        } catch (error) {
            console.error('Auth Error:', error.response || error);
            const errorMsg = error.response?.data?.message || error.response?.data || 'Something went wrong. Please try again.';
            toast.error(errorMsg);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-vh-100 d-flex align-items-center justify-content-center p-4" 
             style={{ 
                 background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)', 
                 fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
             }}
        >
            <div className="container p-0" style={{ maxWidth: '1100px' }}>
                <div className="row g-0 bg-white shadow-lg rounded-5 overflow-hidden">
                    
                    {/* LEFT SIDE: Branding & Illustration */}
                    <div className="col-lg-6 d-none d-lg-flex flex-column justify-content-center p-5 text-white"
                         style={{ 
                             background: 'linear-gradient(135deg, #7B61FF 0%, #5A3FD9 100%)',
                             position: 'relative'
                         }}
                    >
                        <div className="mb-4">
                            <h2 className="fw-bold display-5 mb-3">RoadMap Tracker</h2>
                            <p className="opacity-75 fs-5">Stay consistent. Track your daily growth.</p>
                        </div>
                        
                        {/* Professional Illustration */}
                        <div className="text-center my-4">
                            <img 
                                src="https://cdni.iconscout.com/illustration/premium/thumb/roadmap-4017056-3337050.png" 
                                alt="Roadmap Illustration" 
                                className="img-fluid" 
                                style={{ maxHeight: '300px', filter: 'drop-shadow(0 10px 20px rgba(0,0,0,0.2))' }}
                            />
                        </div>

                        <div className="mt-3 text-center">
                            <p className="fw-light opacity-75 fs-6 mb-0">
                                "The secret of getting ahead is getting started."
                            </p>
                            <p className="fw-bold small opacity-75 mt-1">— Mark Twain</p>
                        </div>
                        
                        {/* Background Decorative Blob */}
                        <div style={{ 
                            position: 'absolute', 
                            top: '-100px', 
                            right: '-100px', 
                            width: '300px', 
                            height: '300px', 
                            background: 'rgba(255,255,255,0.1)', 
                            borderRadius: '50%' 
                        }}></div>
                        <div style={{ 
                            position: 'absolute', 
                            bottom: '-150px', 
                            left: '-150px', 
                            width: '400px', 
                            height: '400px', 
                            background: 'rgba(255,255,255,0.05)', 
                            borderRadius: '50%' 
                        }}></div>
                    </div>

                    {/* RIGHT SIDE: Form */}
                    <div className="col-lg-6 bg-white p-4 p-md-5">
                        <div className="d-flex justify-content-center mb-4 d-lg-none">
                            <div className="bg-primary text-white p-3 rounded-3 shadow-sm">
                                <h4 className="fw-bold m-0">RoadMap</h4>
                            </div>
                        </div>

                        <div className="mx-auto" style={{ maxWidth: '400px' }}>
                            <div className="text-center mb-5">
                                <div className="bg-primary bg-opacity-10 text-primary rounded-circle d-inline-flex align-items-center justify-content-center p-3 mb-3" style={{ width: '64px', height: '64px' }}>
                                    <FaUser size={24} />
                                </div>
                                <h3 className="fw-bold mb-1">{isLogin ? 'Welcome Back' : 'Create Account'}</h3>
                                <p className="text-muted small m-0">
                                    {isLogin ? 'Sign in to track your progress' : 'Start tracking your progress today'}
                                </p>
                            </div>

                            <motion.form 
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ duration: 0.5 }}
                                className="d-flex flex-column gap-3"
                                onSubmit={handleSubmit}
                            >
                                {/* Full Name - Only for Register */}
                                {!isLogin && (
                                    <div className="form-floating">
                                        <input 
                                            type="text" 
                                            className="form-control rounded-3 border-light-subtle" 
                                            id="fullName" 
                                            name="fullName"
                                            placeholder="Full Name" 
                                            value={formData.fullName}
                                            onChange={handleChange}
                                        />
                                        <label htmlFor="fullName" className="text-muted small">Full Name</label>
                                    </div>
                                )}

                                {/* Username */}
                                <div className="form-floating position-relative">
                                    <input 
                                        type="text" 
                                        className="form-control rounded-3 border-light-subtle" 
                                        id="username" 
                                        name="username"
                                        placeholder="Username" 
                                        value={formData.username}
                                        onChange={handleChange}
                                    />
                                    <label htmlFor="username" className="text-muted small">Username</label>
                                    <FaUser className="position-absolute text-muted" style={{ right: '15px', top: '50%', transform: 'translateY(-50%)', fontSize: '14px' }} />
                                </div>

                                {/* Email - Only for Register */}
                                {!isLogin && (
                                    <div className="form-floating position-relative">
                                        <input 
                                            type="email" 
                                            className="form-control rounded-3 border-light-subtle" 
                                            id="email" 
                                            name="email"
                                            placeholder="name@example.com" 
                                            value={formData.email}
                                            onChange={handleChange}
                                        />
                                        <label htmlFor="email" className="text-muted small">Email address</label>
                                        <FaEnvelope className="position-absolute text-muted" style={{ right: '15px', top: '50%', transform: 'translateY(-50%)', fontSize: '14px' }} />
                                    </div>
                                )}

                                {/* Password */}
                                <div className="form-floating position-relative">
                                    <input 
                                        type="password" 
                                        className="form-control rounded-3 border-light-subtle" 
                                        id="password" 
                                        name="password"
                                        placeholder="Password" 
                                        value={formData.password}
                                        onChange={handleChange}
                                    />
                                    <label htmlFor="password" className="text-muted small">Password</label>
                                    <FaLock className="position-absolute text-muted" style={{ right: '15px', top: '50%', transform: 'translateY(-50%)', fontSize: '14px' }} />
                                </div>

                                {/* Submit Button */}
                                <motion.button 
                                    whileHover={{ scale: 1.02, boxShadow: "0px 5px 15px rgba(123, 97, 255, 0.3)" }}
                                    whileTap={{ scale: 0.98 }}
                                    type="submit" 
                                    disabled={loading}
                                    className="btn border-0 text-white fw-bold py-3 rounded-3 shadow-sm mt-2 d-flex align-items-center justify-content-center"
                                    style={{ background: 'linear-gradient(135deg, #7B61FF 0%, #5A3FD9 100%)' }}
                                >
                                    {loading ? (
                                        <><FaSpinner className="fa-spin me-2" /> Processing...</>
                                    ) : (
                                        <>{isLogin ? 'Login' : 'Create Account'} <FaArrowRight className="ms-2" size={14} /></>
                                    )}
                                </motion.button>

                                {/* Toggle Switch */}
                                <div className="text-center mt-3">
                                    <span className="text-muted small me-2">
                                        {isLogin ? "Don't have an account?" : "Already have an account?"}
                                    </span>
                                    <button 
                                        type="button"
                                        onClick={() => {
                                            setIsLogin(!isLogin);
                                            setFormData({ fullName: '', username: '', email: '', password: '' }); // Clear inputs when toggling
                                        }}
                                        className="btn btn-link text-decoration-none fw-bold p-0"
                                        style={{ color: '#7B61FF' }}
                                    >
                                        {isLogin ? 'Register' : 'Login'}
                                    </button>
                                </div>
                            </motion.form>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AuthPages;
